package org.codex.nfsugpreview;
import java.nio.*;import java.nio.file.*;import java.util.*;
public final class RoadOccurrenceBindingTest {
 static final class Record{int index;long epoch,serial,begin,end;int page;long[] identity;byte[] raw;long ordinal;}
 static void ok(boolean v,String why){if(!v)throw new AssertionError(why);}
 public static void main(String[] args)throws Exception{
  Path dir=Paths.get(args[0]);NativeRoadBindings.Candidate[] candidates=RoadBindingsTest.candidates(dir,0),reversed=candidates.clone();for(int i=0;i<reversed.length/2;i++){NativeRoadBindings.Candidate c=reversed[i];reversed[i]=reversed[reversed.length-1-i];reversed[reversed.length-1-i]=c;}
  int snapshots=0,roads=0;NativeSceneSnapshot repeated=null;
  try(DirectoryStream<Path> files=Files.newDirectoryStream(dir,"race-background-*.nrb")){for(Path path:files){NativeSceneSnapshot scene=new NativeBackgroundScene(Files.readAllBytes(path)).sky.scene;NativeRoadBindings a=new NativeRoadBindings(scene,candidates),b=new NativeRoadBindings(scene,reversed);ok(a.count()==b.count(),"Order-dependent count");for(int i=0;i<a.count();i++){NativeRoadBindings.Binding x=a.binding(i),y=b.binding(i);ok(x.owner==y.owner&&x.command==y.command&&x.empty==y.empty&&(x.empty||x.asset.ordinal==y.asset.ordinal),"Candidate storage order changed binding");}for(int i=0;i<scene.geometryCount();i++)if(scene.geometry(i).serial==17)repeated=scene;snapshots++;roads+=a.count();}}
  ok(repeated!=null&&snapshots==9&&roads==86,"Fixture coverage");ByteBuffer packed=ByteBuffer.wrap(Files.readAllBytes(dir.resolve("road-candidates.bin"))).order(ByteOrder.LITTLE_ENDIAN);int count=packed.getInt();List<Record> records=new ArrayList<>();
  for(int i=0;i<count;i++){Record r=new Record();r.index=i;r.epoch=packed.getLong();r.serial=Integer.toUnsignedLong(packed.getInt());r.begin=Integer.toUnsignedLong(packed.getInt());r.end=Integer.toUnsignedLong(packed.getInt());r.page=packed.getInt();r.identity=new long[5];for(int j=0;j<5;j++)r.identity[j]=Integer.toUnsignedLong(packed.getInt());int size=packed.getInt();if(size==0){packed.position(packed.position()+64);continue;}r.raw=new byte[size];packed.get(r.raw);r.ordinal=Integer.toUnsignedLong(ByteBuffer.wrap(r.raw).order(ByteOrder.LITTLE_ENDIAN).getInt(16));if(r.serial==17&&r.identity[2]==139893600L)records.add(r);}
  ok(records.size()==2&&records.get(0).ordinal<records.get(1).ordinal,"Expected distinct original repeated draw ordinals");Record first=records.get(0);byte[] corrupt=first.raw.clone();corrupt[corrupt.length-1]^=1;List<NativeRoadBindings.Candidate> conflict=new ArrayList<>(Arrays.asList(candidates));conflict.add(new NativeRoadBindings.Candidate(first.epoch,first.serial,first.begin,first.end,first.page,first.identity,corrupt));boolean rejected=false;try{new NativeRoadBindings(repeated,conflict.toArray(new NativeRoadBindings.Candidate[0]));}catch(IllegalArgumentException expected){rejected=true;}ok(rejected,"Conflicting same-ordinal bytes accepted");
  List<NativeRoadBindings.Candidate> missing=new ArrayList<>(Arrays.asList(candidates));missing.remove(first.index);rejected=false;try{new NativeRoadBindings(repeated,missing.toArray(new NativeRoadBindings.Candidate[0]));}catch(IllegalArgumentException expected){rejected=true;}ok(rejected,"Missing repeated occurrence accepted");
  System.out.println("PASS_ROAD_OCCURRENCES snapshots="+snapshots+" roads="+roads+" distinct_ordinals="+records.get(0).ordinal+","+records.get(1).ordinal+" reversed_candidates=PASS conflict_and_missing_rejected=2");
 }
}
